    int i = end;
    while (i >= 0) {
        char currChar = headerPart.charAt(i);
        prevChar = currChar;
        if (currChar == '\r' && headerPart.charAt(i - 1) == '\n') {
            if (i == headerPart.length() - 1) {
                return i + 2; // Return 2 because i points to \r
            }
            return i + 1; // Return 1 because i points to \n
        }
        i--;
    }
    return -1; // Return -1 if no \r\n sequence is found
}

