public IsomorphicGraphMapping<V, E> computeIdentityAutomorphism(Graph<V, E> graph) {
        HashSet<String> vertexNames = new HashSet<>();
        for (V vertex : graph.getVertices()) {
            vertexNames.add(vertex.getName());
        }

        HashMap<String, String> originalToIdem = new HashMap<>();

        for (String vertex : vertexNames) {
            HashSet<String> equivalenceClasses = new HashSet<>();
            equivalenceClasses.add(vertex);

            for (V neighbor : graph.getNeighbors(vertex)) {
                if (vertexNames.contains(neighbor.getName()) && !equivalenceClasses.contains(neighbor.getName())) {
                    equivalenceClasses.add(neighbor.getName());
                }
            }

            if (equivalenceClasses.size() > 1) {
                String idempotent = "";
                for (String name : equivalenceClasses) {
                    idempotent += name;
                    idempotent += ",";
                }
                idempotent = idempotent.substring(0, idempotent.length() - 1);

                originalToIdem.put(vertex.getName(), idempotent);
            } else {
                originalToIdem.put(vertex.getName(), vertex.getName());
            }
        }

        HashMap<String, HashMap<String, String>> idemToOriginal = new HashMap<>();
        for (String key : originalToIdem.keySet()) {
            idemToOriginal.put(originalToIdem.get(key), new HashMap<>());
            idemToOriginal.get(originalToIdem.get(key)).put(key, originalToIdem.get(key));
        }

        IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<>(vertexNames.size(), mappings, idemToOriginal);
        return mapping;
    }

