public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Calculate the encoded length of the message
    int encodedLength = buffer.computeEncodedLength(message);

    // Write the encoded length to the output stream
    out.writeShort(encodedLength);

    // Write the message to the output stream using the schema
    schema.encode(message, buffer, out, false);

    return encodedLength;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] messageBytes = schema.encode(message);
    int initialMark = buffer.getMark();
    buffer.writerIndex(initialMark + messageBytes.length + 4); // Prepend length
    out.writeInt(initialMark); // Start marker
    out.write(messageBytes);
    buffer.resetToMark();
    int size = initialMark - buffer.writerIndex() + 1;
    buffer.writerIndex(initialMark);

    if (size >= 1024) {
        buffer.free(); // Free the buffer when the size reaches a certain threshold
        out.flush(); // Ensure all data is written immediately
    }

    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        schema.writeDelimitedTo(bos, message);
        byte[] bytes = bos.toByteArray();
        out.write(bytes.length);
        out.write(bytes);
        return bytes.length;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throwsIOException {
    byte[] messageBytes = schema.encode(message);
    int totalLength = messageBytes.length + 4; // 4 = length of the message length
    out.write(totalLength);
    out.write(messageBytes);
    return totalLength;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    session.write16th(buffer.length());
    out.writeDirect(buffer);
    session.writeLen(buffer.remaining());
    out.writeDirect(buffer, 0, buffer.remaining());
    return buffer.limit();
}

