public List<TimeRange> buildTimeRanges(long start, long end) {
    // Initialize the list to store the time ranges
    List<TimeRange> timeRanges = new ArrayList<>();

    // Ensure the start time is less than end time
    if (start >= end) {
        throw new IllegalArgumentException("Start time must be less than end time");
    }

    // Calculate the duration for fetching data
    int fetchDataDuration = FETCH_DATA_DURATION;

    // Calculate the number of time ranges to split
    int numRanges = (int) Math.ceil((end - start) / fetchDataDuration);

    // Calculate the start time of each time range
    for (int i = 0; i < numRanges; i++) {
        long rangeStart = start + i * fetchDataDuration + 1;
        long rangeEnd = rangeStart + fetchDataDuration - 1;

        // Append the time range to the list
        timeRanges.add(new TimeRange(rangeStart, rangeEnd));
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> result = new ArrayList<>();
    // Calculate the number of seconds within the range
    long durationSeconds = end - start;
    // Split the range into equal parts, keeping each part less than FETCH_DATA_DURATION seconds
    long intervalLength = Math.min(FETCH_DATA_DURATION, durationSeconds) / 60;
    long maxTimeInParts = 30; // Maximum number of intervals defined in the problem method
    long intervals = (int) Math.ceil((double) durationSeconds / intervalLength);
    for (long i = 0; i < intervals; i++) {
        long startTime = start + i * intervalLength * 60; // Convert duration back to seconds format
        long endTime = startTime + intervalLength * 60;
        result.add(new TimeRange(startTime, endTime)); // Create and add TimeRange objects to the list
    }
    return result;
}

