public static int computeUTF8Size(final CharSequence str,final int index,final int len) {
    int size = 0;
    int utf8Len;
    int i = index;
    while (i < index + len && utf8Len >= 0) {
        int currChar = str.charAt(i);
        if (currChar >= 0xC0 && currChar <= 0xDF) {
            utf8Len = currChar & 0x1F;
            i++;
        } else if (currChar >= 0xE0 && currChar <= 0xEF) {
            utf8Len = currChar & 0x0F;
            i++;
        } else {
            utf8Len = currChar & 0x07;
            i++;
        }
        size += utf8Len + 1;
    }
    return size;
}

