            size += 1; // Single-byte character
        } else if (c >= 0x0080 && c <= 0x07ff) {
            size += 2; // Two-byte character
        } else if (c >= 0x0800 && c <= 0xffff) {
            size += 3; // Three-byte character
        } else {
            size += 4; // Four-byte character
        }
    }
    return size;
}

