    for (int i = 0; i < minLength; i++) {
        char charStr = str.charAt(i);
        char charPrefix = prefix.charAt(i);

        if (Character.toUpperCase(charStr) != Character.toUpperCase(charPrefix)) {
            return false;
        }
    }

    // If all characters in the prefix are uppercase and the lengths match, it could also match entirely, so check for exact length match
    if (str.length() == prefix.length() && str.equals(prefix)) {
        return true;
    }

    return true;
}

