public void removeFromTreeEdgeList() {
    // Check for null edges
    if (edgeList == null || edgeList.isEmpty()) {
        return;
    }

    // Removing the edge from the first doubly linked list
    DoublyLinkedListNode previousNode = edgeList.getFirstNode();
    DoublyLinkedListNode currentNode = edgeList.getFirstNode();

    while (currentNode != null) {
        if (currentNode.getData().equals(edge)) {
            // Traverse to previous node
            while (currentNode.getPreviousNode() != null && currentNode.getPreviousNode().getData() != edge) {
                currentNode = currentNode.getPreviousNode();
            }
            if (currentNode.getPreviousNode() == null) {
                edgeList.setFirstNode(edgeList.getNextNode());
            } else {
                previousNode.setNextNode(currentNode.getNextNode());
            }
            currentNode=null;
            edgeList.size--;
            return;
        }

        previousNode = currentNode;
        currentNode = currentNode.getNextNode();
    }
}

