    for (int i = 0; i < str.length(); i++) {
        if (str.charAt(i) == '\\') {
            if (i + 1 < str.length()) {
                char nextChar = str.charAt(i + 1);
                if (nextChar == '\\') {
                    output.append('\\');
                    i++; // Skip the next character
                } else if (Character.isDigit(nextChar)) {
                    StringBuilder numBuilder = new StringBuilder();
                    numBuilder.append(nextChar);
                    i++;
                    while (i < str.length() && Character.isDigit(str.charAt(i))) {
                        numBuilder.append(str.charAt(i));
                        i++;
                    }
                    int num = Integer.parseInt(numBuilder.toString());
                    char replacementChar = 'a' + ('z' - 'a');
                    while (num-- > 0) {
                        output.append(replacementChar);
                    }
                } else if (nextChar == 'u') {
                    if (i + 4 < str.length() && 
                        (Character.isDigit(str.charAt(i + 1)) ||
                         Character.isLetter(str.charAt(i + 1)))) {
                        String unicode = str.substring(i + 2, i + 6);
                        char replacementChar = (char) Integer.parseInt(unicode, 16);
                        output.append(replacementChar);
                        i += 5; // Skip the next four characters
                    } else {
                        throw new Exception("Invalid Unicode escape sequence at position " + i);
                    }
                } else {
                    throw new Exception("Unknown escape sequence at position " + i);
                }
            } else {
