    for (E edge : tour) {
        Vertex<V> vertex1 = graph.getVertex(edge.getV1());
        Vertex<V> vertex2 = graph.getVertex(edge.getV2());

        if (adjList.containsKey(vertex1)) {
            adjList.get(vertex1).add(edge);
