            list.add(edge);
            adjList.put(vertex2, list);
        }
    }

    // Create a graph path object
    GraphPath<V,E> path = new GraphPath<V,E>();

    // Add the edges of the tour to the graph path
    for (E edge : tour) {
        path.addEdge(graph.getEdge(edge));
    }

    return path;
}

