            addEdgesToGraph(vertices, edgeToEdge);
        }
        edgeToVertices.put(edge, vertices);
    }

    // Construct the tour using the edges
    List<Vertex> tourVertices = new ArrayList<>();
    for (E edge : tour) {
        tourVertices.addAll(edgeToVertices.get(edge));
    }

    // Create a vertices-to-index mapping for quick lookups
    Map<Vertex, Integer> vertexIndex = new HashMap<>();
    for (int i = 0; i < tourVertices.size(); i++) {
        vertexIndex.put(tourVertices.get(i), i);
    }

    // Build the graph path
    List<Collection<Integer>> path = new ArrayList<>();
    for (int i = 0; i < tourVertices.size(); i++) {
        List<Integer> edgeIndices = new ArrayList<>();
        for (E edge : edgeToVertices.keySet()) {
            if ( edgeToVertices.get(edge).contains(vertexIndex.get(tourVertices.get(i))) {
                edgeIndices.add(edgeIndex.get(tourVertices.get(i)));
            }
        }
        path.add(edgeIndices);
    }

    return new GraphPath<>(graph, path);
}

void edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    GraphPath<V,E> path = new GraphPath<V,E>();
    for (E edge : tour) {
        path.addEdge(graph.getEdge(edge.getSource(), edge.getTarget()));
    }
    return path;
}

