        throw new IllegalArgumentException("Invalid bucket label: " + minLabel);
    }

    // Step 1: Clear the bucket with label minLabel
    bucketsByLabel.get(minLabel).clear();
    labels.set(minLabel, 0);

    // Step 2: Reload the bucket with label 0
    if (bucketsByLabel.get(0).isEmpty()) {
        return;
    }

    // Step 3: Relabel the vertices in the bucket with label 0
    for (Integer vertexLabel : labels) {
        if (vertexLabel == minLabel) {
            labels.remove(vertexLabel);
            labels.addFirst(vertexLabel);
        }
    }
