void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (minLabel < 0 || minLabel >= labels.size() || bucketsByLabel.size() == 0 || labels.isEmpty() || bucketsByLabel.get(minLabel) == null) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Clear the bucket with the minimum label
    ListIterator<Set<Integer>> it = bucketsByLabel.listIterator();
    while (it.hasNext() && it.next() != bucketsByLabel.get(minLabel)) {
        it.next();
    }
    if (it.hasNext()) {
        it.remove();
    }

    // Update the labeling
    for (int i = minLabel; i < labels.size(); i++) {
        int label = labels.get(i);
        labels.set(i, 0);
        for (Set<Integer> set : bucketsByLabel) {
            if (set.contains(label)) {
                labels.set(i, label);
                break;
            }
        }
    }
