        if (label != minLabel) {
            bucketsByLabel.get(label - 1).remove(label); // Move vertices to new bucket with label 0
            bucketsByLabel.set(newLabel, new HashSet<>()); // Create a new bucket with label 0
            bucketsByLabel.get(newLabel).add(label); // Assign vertices to newly created bucket with label 0
