private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Make a copy of the set at minLabel to avoid modifying it while iterating
    Set<Integer> bucketToMove = new HashSet<>(bucketsByLabel.get(minLabel));
    // Clear the set at minLabel
    bucketsByLabel.get(minLabel).clear();

    // Iterate over the set at minLabel
    for (int vertex : bucketToMove) {
        // Re-map the vertex to the label 0
        int newLabel = 0;
        if (labels.contains(vertex)) {
            newLabel = labels.indexOf(vertex);
        } else {
            labels.add(vertex);
            newLabel = labels.size() - 1;
        }

        // Add the vertex to the bucket with the new label
        bucketsByLabel.get(newLabel).add(vertex);

        // If the new label was previously full, update the minLabel
        if (newLabel == minLabel && bucketsByLabel.get(newLabel).size() >= bucketsByLabel.get(0).size()) {
            minLabel = 0;
        }
    }
}

