    }
}

void pop(final int elements) {
    if (elements < 0) {
        throw new IllegalArgumentException("elements must be non-negative");
    }
    if (elements > stack.length) {
        throw new ArrayIndexOutOfBoundsException("Required elements exceed stack capacity");
    }
    int poppedElements = Math.min(elements, stack.length);
    for (int i = 0; i < poppedElements; i++) {
        stack[pos + poppedElements - 1 - i] = stack[pos];
        stack[pos] = null;
    }
    pos -= poppedElements;
}

private void pop(final int elements){
    // Ensure the input parameter is valid
    if (elements < 0) {
        throw new IllegalArgumentException("Number of elements to pop must be non-negative");
    }

    // Remove the elements from the stack, adjusting positions
    for (int i = 0; i < elements; i++) {
        if (pos == 0) {
            throw new EmptyStackException("Attempt to pop from an empty stack");
        }
        pos--;
    }
}

