        throw new IllegalArgumentException("Invalid buffer or name start index");
    }

    int endIndex = nameStart;
    // Traverse through the buffer to find the end index of the name to abbreviate
    for (; endIndex < buf.length; endIndex++) {
        if (buf.charAt(endIndex) == ' ') {
            break;
        }
    }

    // Set the abbreviation in the buffer
    buf.setLength(nameStart).append(endIndex - nameStart > 0 ? buf.substring(nameStart, endIndex) : "");
}

