    if (graph == null || vertices == null || graph.isEmpty() || vertices.isEmpty()) {
        return false;
    }

    for (V vertex : vertices) {
        Set<V> neighbors = graph.neighbors(vertex);
        if (vertices.size() != neighbors.size()) {
            return false;
        }
        for (V neighbor : vertices) {
            if (neighbor == vertex || !neighbors.contains(neighbor)) {
                return false;
            }
        }
    }

    return true;
}

