            return false;
        }
    }
    return true;
}

public <V,E> boolean isClique(Graph<V,E> graph,Set<V> vertices){
    int n = vertices.size();
    if (n < 2) {
        return true;
    }

    LinkedList<UndirectedEdge<E>> undirectedEdges = new LinkedList<>();
    for (V v : vertices) {
        for (V u : vertices) {
            if (u != v && graph.getEdge(v, u) != null) {
                undirectedEdges.add(new UndirectedEdge<>(v, u));
            }
        }
    }

    boolean[] neighborhood = new boolean[n];
    for (UndirectedEdge<E> edge : undirectedEdges) {
        int v = edge.source();
        int u = edge.target();
        neighborhood[v] = true;
        neighborhood[u] = true;
    }

    boolean clique = true;
    for (int i = 0; i < n; i++) {
        if (!neighborhood[i]) {
            clique = false;
            break;
        }
    }

    return clique;
}

