public static String applyRelativePath(String path, String relativePath) {
        if (path == null || relativePath == null) {
            throw new IllegalArgumentException("Both path and relativePath cannot be null");
        }

        if (relativePath.isEmpty()) {
            return path;
        }

        // Ensure the relative path starts with a slash
        if (!relativePath.startsWith("/")) {
            relativePath = "/" + relativePath;
        }

        // Split the paths into parts
        String[] parts1 = path.split("/");
        String[] parts2 = relativePath.split("/");

        // Append the relative path parts to the original parts
        List<String> combinedParts = new ArrayList<>();
        combinedParts.addAll(Arrays.asList(parts1));
        combinedParts.addAll(Arrays.asList(parts2));

        // Join the parts back into a single string
        String result = String.join("/", combinedParts);

        return result;
    }

