private static int getLastSeparatorIndex(String filename) {
    if (filename == null) {
        return -1;
    }

    char[] chars = filename.toCharArray();
    for (int i = chars.length - 1; i >= 0; i--) {
        if (chars[i] == '\\' || chars[i] == '/') {
            return i;
        }
    }

    return -1;
}

