    if (str == null || str.length() == 0 || index < 0 || index >= str.length() || substring == null || substring.length() == 0) {
        throw new IllegalArgumentException("Invalid input");
    }
    for (int i = 0; i < substring.length(); i++) {
        if (index + i >= str.length() || str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    if (str == null || substring == null) {
        throw new IllegalArgumentException("Both str and substring cannot be null.");
    }

    if (index < 0 || index > str.length()) {
        throw new IndexOutOfBoundsException("Index must be within the bounds of the string.");
    }

    int strLength = str.length();
    int substringLength = substring.length();

    int i = index;
    int j = 0;

    while (i < strLength && j < substringLength && str.charAt(i) == substring.charAt(j)) {
        i++;
        j++;
    }

    if (j == substringLength) {
        return true;
    }

    return false;
}

