public static String toString(final char ch) {
    if (ch < 32 || ch > 126) {
        throw new IllegalArgumentException("Invalid character: " + ch);
    }

    if (ch < 95) {
        return new String("[" + ch + "]");
    } else {
        return new String("[\\u" + Integer.toHexString(ch) + "]");
    }
}

public static String toString(final char ch) {
    if (ch == 0) {
        return " "; // extra '\u0000' for putChar that inserts 2 '\u0000' characters for zeroes
    }
    if (ch <= 0x7F) {
        final char c1 = (char) (0xFF00 | ch);
        final char c2 = (char) (0x00F7 | ch);
        return new String(new char[]{c1, c2});
    }
    // TODO: add support for unicode characters
    return String.valueOf(ch);
}

