    // continuously attempt to read a tag from the input stream
    while (true) {
        // read the next byte of data
        int byteData = inputStream.read();

        // if no byte is available
        if (byteData == -1) {
            // return 0 as indication of reaching EOF
            return 0;
        }

        // isolate the high 4 bits of the byte to get the tag number
        int tagNumber = (byteData & 0xF0) >> 4;

        // if the tag is zero, indicate that we have reached EOF
        if (tagNumber == 0) {
            return 0;
        }

        // return the tag number
        return tagNumber;
    }
}

