public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (InputStream input = new FileInputStream(file);
         BufferedReader reader = new BufferedReader(new InputStreamReader(input))) {
        SimpleDateFormat dateFormat = new SimpleDateFormat(DATE_TIME_FORMAT);
        Map<String,ThreadSnapshot> threadSnapshotsMap = new HashMap<>();

        String line;
        while ((line = reader.readLine()) != null) {
            String[] fields = line.split("\t");
            if (fields.length != 7) continue;
            String timestamp = fields[0];
            try {
                long time = dateFormat.parse(timestamp).getTime();
                if (!timeRanges.contains(time)) continue;
                if (threadSnapshotsMap.containsKey(timestamp)) continue;
                ThreadSnapshot snapshot = new ThreadSnapshot(time);
                double cpuUsage = Double.parseDouble(fields[1]);
                double memoryUsage = Double.parseDouble(fields[2]);
                int threadCount = Integer.parseInt(fields[3]);
                double cpuUtilization = Double.parseDouble(fields[4]);
                int threadTime = Integer.parseInt(fields[5]);
                snapshot.setCpuUsage(cpuUsage);
                snapshot.setMemoryUsage(memoryUsage);
                snapshot.setThreadCount(threadCount);
                snapshot.setCpuUtilization(cpuUtilization);
                snapshot.setThreadTime(threadTime);
                threadSnapshotsMap.put(timestamp, snapshot);
            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (timeSnapshotsMap.containsKey(timeRange.getStartTime() + ":0") && timeSnapshotsMap.containsKey(timeRange.getEndTime() + ":0")) {
                ThreadSnapshot startSnapshot = timeSnapshotsMap.get(timeRange.getStartTime() + ":0");
                ThreadSnapshot endSnapshot = timeSnapshotsMap.get(timeRange.getEndTime() + ":0");
                if (startSnapshot == null || endSnapshot == null) continue;
                long duration = endSnapshot.getTime() - startSnapshot.getTime();
                ThreadSnapshot mergedSnapshot = new ThreadSnapshot(startSnapshot.getTime() + ":0", duration, startSnapshot.getThreadCount(), startSnapshot.getCpuUsage(), startSnapshot.getMemoryUsage(), startSnapshot.getCpuUtilization(), startSnapshot.getThreadTime());
                threadSnapshots.add(mergedSnapshot);
            }
        }
    } catch (IOException e) {
        e.printStackTrace();
    }
    return threadSnapshots;
}
